Добавляем nginx в автозапуск и запускаем:
sudo systemctl enable --now nginx
Далее можно добавить в /usr/local/bin скрипт для проверки статуса работы серверов СФР
cat << 'EOF' > /usr/local/bin/fss-status
#!/bin/bash
G='\033[1;32m'
C='\033[1;36m'
Y='\033[1;33m'
R='\033[1;31m'
N='\033[0m'

echo -e "${C}==================================================================${N}"
echo -e " 🛡️ ${G}ШЛЮЗ СФР (ГОСТ TLS)${N} | $(hostname) ($(hostname -I | awk '{print $1}')):8080"
echo -e "${C}==================================================================${N}"

OSSL_VER=$(openssl version | awk '{print $1, $2}')
if openssl engine gost 2>/dev/null | grep -q "Reference implementation"; then
 ENG_ST="${G}АКТИВЕН (gost-engine)${N}"
else
 ENG_ST="${R}ОШИБКА${N}"
fi
echo -e " 🔹 Криптоядро : ${Y}${OSSL_VER}${N} | Движок ГОСТ: ${ENG_ST}"

if systemctl is-active --quiet nginx; then
 NGX_MEM=$(ps -C nginx -o rss= | awk '{sum+=$1} END {printf "%.1f MB", sum/1024}')
 NGX_ST="${G}РАБОТАЕТ${N} (RAM: ${Y}${NGX_MEM}${N})"
else
 NGX_ST="${R}ОСТАНОВЛЕН${N}"
fi
echo -e " 🔹 Прокси-сервер : Nginx ($(nginx -v 2>&1 | cut -d/ -f2)) — ${NGX_ST}"

TLS_OUT=$(timeout 4 openssl s_client -connect eln.sfr.gov.ru:443 -tls1_2 </dev/null 2>/dev/null)
CIPHER=$(echo "$TLS_OUT" | awk '/Cipher is/ {print $NF}')
CERT_EXP=$(echo "$TLS_OUT" | openssl x509 -noout -enddate 2>/dev/null | cut -d= -f2)

if [ -n "$CIPHER" ] && [ "$CIPHER" != "(NONE)" ]; then
 echo -e " 🔹 Канал до СФР : ${G}УСТАНОВЛЕН${N} | Шифр: ${Y}${CIPHER}${N}"
 echo -e " 🔹 Сертификат СФР: Действителен до ${Y}${CERT_EXP}${N}"
else
 echo -e " 🔹 Канал до СФР : ${R}НЕТ СВЯЗИ${N}"
fi

HTTP_ELN=$(curl -s -o /dev/null -w "%{http_code} (%{time_total}s)" "http://127.0.0.1:8080/eln?wsdl")
HTTP_SEDO=$(curl -s -o /dev/null -w "%{http_code} (%{time_total}s)" "http://127.0.0.1:8080/sedo?wsdl")
echo -e " 🔹 Маршрут /eln : HTTP ${G}${HTTP_ELN}${N}"
echo -e " 🔹 Маршрут /sedo : HTTP ${G}${HTTP_SEDO}${N}"

echo -e "${C}-------------------- Последние запросы АРМ ЛПУ -------------------${N}"
grep -v "127.0.0.1" /var/log/nginx/fss_access.log 2>/dev/null | tail -n 5 | awk '
{
 code = $9;
 status = code;
 if (code == "200") status = "\033[1;32m200 OK\033[0m";
 else if (code == "500") status = "\033[1;32m200 SOAP-RPC\033[0m";
 else status = "\033[1;31m" code "\033[0m";
 printf " 🕒 %s | IP: %-14s | %-4s %-24s -> %s\n", substr($4,2), $1, substr($6,2), substr($7,1,24), status
}'
echo -e "${C}==================================================================${N}"
EOF

chmod +x /usr/local/bin/fss-status
